package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PrimeFactorProductsTest {
 private String independent(int n){if(n==1)return "1";List<String>terms=new ArrayList<>();int remainder=n;for(int d=2;d<=n;d++)while(remainder%d==0){terms.add(""+d);remainder/=d;}return String.join("*",terms);}
 private boolean correct(int n,String input){Question q=PrimeFactorProducts.make(n);q.answers=new String[]{"poison"};q.expression="poison";return PrimeFactorProducts.check(q,List.of(input)).correct();}
 @Test public void publicFactorProductMultiplicityAndCompressedForms(){for(int n=1;n<=99;n++){Question q=PrimeFactorProducts.make(n);assertEquals(n,PrimeFactorProducts.read(q));String canonical=q.answers[0];q.answers=new String[]{"poison"};q.expression="poison";assertTrue(PrimeFactorProducts.check(q,List.of(independent(n))).correct());assertTrue(PrimeFactorProducts.check(q,List.of(canonical)).correct());if(n>1&&!PrimeRecall.prime(n))assertFalse(PrimeFactorProducts.check(q,List.of(""+n)).correct());}assertTrue(correct(12,"3*2*2"));assertTrue(correct(12,"2^2 × 3"));assertTrue(correct(12,"2 ^ 2 * 3"));assertFalse(correct(23,"2 3"));assertFalse(correct(23,"2\n3"));assertTrue(correct(12,"(2*3)*2"));assertTrue(correct(36,"(3*2)^2"));assertTrue(correct(49,"7^2"));assertTrue(correct(97,"97"));assertTrue(correct(99,"11·3^2"));assertTrue(correct(999983,"999983"));assertTrue(correct(1000000,"2^6*5^6"));assertTrue(correct(1,"1"));Question changed=PrimeFactorProducts.make(12);changed.prompt=changed.prompt.replace("12를","49를");assertTrue(PrimeFactorProducts.check(changed,List.of("7^2")).correct());assertFalse(PrimeFactorProducts.check(changed,List.of("2^2*3")).correct());assertFalse(correct(12,"2*3"));assertFalse(correct(12,"4*3"));assertFalse(correct(12,"6*2"));assertFalse(correct(12,"2^3*3"));}
 @Test public void boundedGrammarRejectsNonPrimeAtomsOtherOperationsAndOverflow(){for(String input:List.of("12","4*3","6*2","1*2*2*3","0*2","2+2+2+2+2+2","24/2","-2*-2*3","2^0*3","2^-1*3","2^21","2^20","(4)^1*3","2**3","2(2*3)","(2*3","2^2^2","2.0*2*3","2^9999999","999999999999","","2^19*2","((2*3))^20","(".repeat(17)+"2"+")".repeat(17)," ".repeat(129)+"2")){assertFalse(input,correct(12,input));}assertTrue(correct(2,"(".repeat(16)+"2"+")".repeat(16)));assertFalse(correct(1,"(1)"));assertFalse(correct(1,"1*1"));assertFalse(correct(2,"1*2"));}
 @Test public void publicBoundsPoisonAndDefinitionOnlyHelp(){for(int n:new int[]{1,12,49,97,99,999983,1000000}){Question q=PrimeFactorProducts.make(n);q.answers=new String[]{"poison"};q.expression="poison";PrimeFactorProducts.attach(q);assertFalse(q.studyGuide.transfer);assertEquals(1,q.studyGuide.frames.size());assertEquals("prime-factor-product-v1",q.studyGuide.teachingVersion);assertEquals(n==1?"1":"2",q.studyGuide.frames.get(0).expected);assertEquals(n==1?"빈 곱의 값 = ":"소수의 양의 약수 개수 = ",q.studyGuide.frames.get(0).before);HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(List.of(""),h.restore(null,q.id).entries);}for(int n:new int[]{0,1000001}){assertEquals(-1,PrimeFactorProducts.read(new Question(PrimeFactorProducts.ID,n+"을 소인수의 곱으로 나타내세요.\n소인수가 없으면 빈 곱의 값 1을 쓰세요.","","1")));try{PrimeFactorProducts.make(n);fail();}catch(IllegalArgumentException expected){}}assertEquals(1000000,PrimeFactorProducts.count());assertEquals(1000000,PrimeFactorProducts.read(PrimeFactorProducts.indexed(999999)));}
 @Test public void narrowPublicSupplyFreshThenOldestWithoutMillionArray(){CurriculumLimits limits=new CurriculumLimits("minGiven=10;maxGiven=15;maxResult=15;nonnegative=true");Map<String,Integer>recent=new LinkedHashMap<>();Set<Integer>seen=new HashSet<>();Random pinned=new Random(){@Override public int nextInt(int bound){return 0;}};for(int i=0;i<6;i++){Question q=PrimeFactorProducts.next(pinned,limits,recent);assertTrue(limits.allows(q));assertTrue(seen.add(PrimeFactorProducts.read(q)));recent.put(q.signature(),i);}assertEquals(Set.of(10,11,12,13,14,15),seen);assertEquals(0,(int)recent.get(PrimeFactorProducts.next(pinned,limits,recent).signature()));}
}




